"""A very simple evaluator for a small subset of Forth."""

import re

_NUMBER_RE = re.compile(r"-?\d+\Z")


class StackUnderflowError(Exception):
    pass


def _underflow():
    raise StackUnderflowError("Insufficient number of items in stack")


def _add(stack):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def _sub(stack):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def _mul(stack):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def _div(stack):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    stack.append(a // b)


def _dup(stack):
    if len(stack) < 1:
        _underflow()
    stack.append(stack[-1])


def _drop(stack):
    if len(stack) < 1:
        _underflow()
    stack.pop()


def _swap(stack):
    if len(stack) < 2:
        _underflow()
    stack[-2], stack[-1] = stack[-1], stack[-2]


def _over(stack):
    if len(stack) < 2:
        _underflow()
    stack.append(stack[-2])


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _is_number(token):
    return _NUMBER_RE.match(token) is not None


def _make_word(body):
    def execute(stack):
        for instruction in body:
            if isinstance(instruction, int):
                stack.append(instruction)
            else:
                instruction(stack)

    return execute


def evaluate(input_data):
    stack = []
    words = {}

    for line in input_data:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0] == ":":
            if len(tokens) < 3 or tokens[-1] != ";":
                raise ValueError("illegal operation")
            name = tokens[1].lower()
            if _is_number(tokens[1]):
                raise ValueError("illegal operation")
            body = []
            for token in tokens[2:-1]:
                if _is_number(token):
                    body.append(int(token))
                else:
                    word = token.lower()
                    if word in words:
                        body.append(words[word])
                    elif word in _BUILTINS:
                        body.append(_BUILTINS[word])
                    else:
                        raise ValueError("undefined operation")
            words[name] = _make_word(body)
        else:
            for token in tokens:
                if _is_number(token):
                    stack.append(int(token))
                else:
                    word = token.lower()
                    if word in words:
                        words[word](stack)
                    elif word in _BUILTINS:
                        _BUILTINS[word](stack)
                    else:
                        raise ValueError("undefined operation")

    return stack
